def paths(H,W,seed):
    # dp over rows: count of billiard paths reaching each cell; track min reflections too
    from collections import defaultdict
    cur={(0,seed):(1,0)}  # (count, min_reflections)
    rows=[]
    for r in range(H):
        rows.append(dict(cur))
        nxt=defaultdict(list)
        for (c,(cnt,refl)) in cur.items():
            for d in (-1,1):
                nc=c+d; nrefl=refl
                if nc<0 or nc>W-1:
                    nc=c-d; nrefl=refl+1
                nxt[(nc,)].append((cnt,nrefl,d))
        new={}
        for c,lst in nxt.items():
            tot=sum(x[0] for x in lst)
            mr=min(x[1] for x in lst)
            new[c[0]]=(tot,mr)
        cur=new
    return rows
