def solve(inp):
    W=len(inp); H=W; s=inp.index(2)
    g=[[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if r<=min(s,W-1-s) and (c==s-r or c==s+r):
                g[r][c]=2
            elif (c-r-s)%4==0 and abs(c-s)<=r:
                g[r][c]=1
    return g
